// Package contractscan 是三份契约守卫（「契约类型写了没人产出 = 契约不存在」）
// 共用的机械部分：认 thriftgo 生成物、抽出它声明的类型、扫出引用点。
//
// 判据留在守卫自己身上（什么算违反、报什么错、扫哪个根），这里只有机械、
// 没有立场。三份守卫问的是三个问题（两个服务的契约各一份、共用词汇一份），
// 不该合并；但「怎么读生成物、怎么抽字段、怎么找 mention」是同一件事，
// 抄三份就会漂 —— 而漂的那份决定守卫认不认得出破契约。
//
// 依赖只有标准库：守卫要能在任何上下文里跑，不该拖着业务依赖。
package contractscan

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"os"
	"path/filepath"
	"reflect"
	"strconv"
	"strings"
)

// IsGenerated 报告 path 是不是 thriftgo 生成物。
//
// 认的是文件头（"Code generated by thriftgo"），不是文件名清单：清单要
// 跟着 gen 走，漏一行守卫就静默放行一个手写文件；文件头是生成器自己写
// 的，改不了名也仿不了 —— 至少仿不了还不被发现。
func IsGenerated(path string) bool {
	f, err := os.Open(path)
	if err != nil {
		return false
	}
	defer f.Close()
	buf := make([]byte, 4096)
	n, _ := f.Read(buf)
	return strings.Contains(string(buf[:n]), "Code generated by thriftgo")
}

// GeneratedFiles 返回 dir 下 thriftgo 生成物的文件路径（排序稳定）。
func GeneratedFiles(dir string) ([]string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var out []string
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
			continue
		}
		path := filepath.Join(dir, e.Name())
		if IsGenerated(path) {
			out = append(out, path)
		}
	}
	return out, nil
}

// Field 是生成物 struct 的一个字段。`A, B string` 这种多名字字段按名字
// 拆成多条（留痕按名字查字段，每个可能被查到的名字都得在）。
type Field struct {
	GoName   string // Go 字段名
	JSONName string // 契约名（json tag 的名）；无 tag 或 "-" ⇒ ""（无契约名）
	GoType   string // 类型源码，如 "*string"、"[]*Asset"、"map[string]*Node"
}

// Type 是生成物上声明的一个类型。
type Type struct {
	Pkg    string   // 声明它的文件的包名
	Name   string   // Go 类型名
	Struct bool     // 是不是 struct（thrift 枚举在 Go 里是命名类型，不是 struct）
	Fields []Field  // struct 的字段；非 struct 为 nil
	Refs   []string // 字段类型里引用到的类型名（依赖边，含重复、含基本类型名）
}

// GoTypes 返回 Go 字段名 → 类型源码。
func (t Type) GoTypes() map[string]string {
	out := make(map[string]string, len(t.Fields))
	for _, f := range t.Fields {
		out[f.GoName] = f.GoType
	}
	return out
}

// JSONTypes 返回契约名 → 类型源码。无契约名的字段（无 tag / "-"）不计。
func (t Type) JSONTypes() map[string]string {
	out := make(map[string]string, len(t.Fields))
	for _, f := range t.Fields {
		if f.JSONName != "" {
			out[f.JSONName] = f.GoType
		}
	}
	return out
}

// Declared 抽出 files 里声明的全部类型（顺序与文件、声明顺序一致）。
//
// struct 带字段与依赖边；其余类型（thrift 枚举等）Fields/Refs 为 nil ——
// 守卫要不要把它们算进「声明了的类型」是守卫的事（model/jms 那份算，两个
// 服务那份不算），这里不替它决定。
func Declared(files []string) ([]Type, error) {
	var out []Type
	for _, path := range files {
		fset := token.NewFileSet()
		f, err := parser.ParseFile(fset, path, nil, 0)
		if err != nil {
			return nil, fmt.Errorf("parse %s: %w", path, err)
		}
		for _, decl := range f.Decls {
			gd, ok := decl.(*ast.GenDecl)
			if !ok || gd.Tok != token.TYPE {
				continue
			}
			for _, spec := range gd.Specs {
				ts, ok := spec.(*ast.TypeSpec)
				if !ok {
					continue
				}
				ty := Type{Pkg: f.Name.Name, Name: ts.Name.Name}
				if st, ok := ts.Type.(*ast.StructType); ok {
					ty.Struct = true
					ty.Fields = fieldsOf(st)
					ty.Refs = refsOf(st)
				}
				out = append(out, ty)
			}
		}
	}
	return out, nil
}

// fieldsOf 抽 struct 的字段。
func fieldsOf(st *ast.StructType) []Field {
	var out []Field
	for _, f := range st.Fields.List {
		typ := goType(f.Type)
		json := jsonName(f)
		for _, n := range f.Names {
			if n.Name == "_" {
				continue
			}
			out = append(out, Field{GoName: n.Name, JSONName: json, GoType: typ})
		}
	}
	return out
}

// refsOf 抽字段类型里引用到的类型名 —— 「这个类型由什么拼出来」的依赖边。
// 基本类型名（string、int64）也会进来；查依赖闭包时它们不在声明集里，
// 自然被忽略。
func refsOf(st *ast.StructType) []string {
	var out []string
	for _, f := range st.Fields.List {
		ast.Inspect(f.Type, func(n ast.Node) bool {
			if id, ok := n.(*ast.Ident); ok {
				out = append(out, id.Name)
			}
			return true
		})
	}
	return out
}

// goType 把类型表达式渲染成源码形状（"*string"、"[]*Asset"）。守卫拿它
// 说「这个字段是 *string」——渲染得不像源码，错误消息就得读者自己猜。
func goType(expr ast.Expr) string {
	switch e := expr.(type) {
	case *ast.Ident:
		return e.Name
	case *ast.StarExpr:
		return "*" + goType(e.X)
	case *ast.SelectorExpr:
		return goType(e.X) + "." + goType(e.Sel)
	case *ast.ArrayType:
		return "[]" + goType(e.Elt)
	case *ast.MapType:
		return "map[" + goType(e.Key) + "]" + goType(e.Value)
	case *ast.IndexExpr:
		return goType(e.X) + "[" + goType(e.Index) + "]"
	case *ast.IndexListExpr:
		parts := make([]string, 0, len(e.Indices))
		for _, idx := range e.Indices {
			parts = append(parts, goType(idx))
		}
		return goType(e.X) + "[" + strings.Join(parts, ", ") + "]"
	default:
		return ""
	}
}

// jsonName 返回字段的契约名（json tag 的名）。无 tag、"-"、空名 ⇒ ""：
// 那种字段没有契约名（Go 的序列化名不是契约，契约是 tag 说的那个）。
//
// tag 用 reflect.StructTag 解析，不是手工切文本：手工切会把
// `risk,omitempty` 当成名，之后查 `risk` 永远扑空 —— 判据一条都不匹配，
// 守卫对什么契约都放行，而且放行得悄无声息（变异测试抓过这一条：把契约
// 字段从 *bool 改成 bool，守卫居然不红）。
//
// 生成物每个字段都带 tag（thriftgo 写的），所以「无 tag」只是防御分支；
// 真出现了，守卫看到的是「无契约名」而不是一个猜出来的名字。
func jsonName(field *ast.Field) string {
	if field.Tag == nil {
		return ""
	}
	tag, err := strconv.Unquote(field.Tag.Value)
	if err != nil {
		return ""
	}
	j, ok := reflect.StructTag(tag).Lookup("json")
	if !ok {
		return ""
	}
	name, _, _ := strings.Cut(j, ",")
	if name == "-" {
		return ""
	}
	return name
}

// References 返回 words 里每个词在 root 目录树下被哪些文件提到（绝对
// 路径，顺序稳定）。「提到」= 文件内容里出现这个词（生成物里全是类型
// 名，那不是「被工具用到」——所以生成物要靠 skip 排掉）。
//
// skip 返回 true 的文件一个字都不看。目录名是 .git 的不进。
func References(root string, skip func(path string) bool, words []string) (map[string][]string, error) {
	refs := map[string][]string{}
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			if d.Name() == ".git" {
				return filepath.SkipDir
			}
			return nil
		}
		if !strings.HasSuffix(path, ".go") {
			return nil
		}
		abs, err := filepath.Abs(path)
		if err != nil {
			return nil
		}
		if skip != nil && skip(abs) {
			return nil
		}
		body, err := os.ReadFile(path)
		if err != nil {
			return nil
		}
		text := string(body)
		for _, w := range words {
			if strings.Contains(text, w) {
				refs[w] = append(refs[w], abs)
			}
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	return refs, nil
}
